content:
{
  "root_cause": "The exclusive 'No, I do not have any of these symptoms' checkbox lacks the required `data-checkbox-exclusive=\"true\"` attribute, so the NHSUK checkboxes module does not treat it as an exclusive option and fails to clear other symptom selections when chosen.",
  "repair_strategy": "Add `data-checkbox-exclusive=\"true\"` to the symptoms-none input element to enable the exclusive behavior defined by the checkboxes component.",
  "edits": [
    {
      "path": "index.html",
      "sha256": "d41d8cd98f00b204e9800998ecf8427e",
      "before": "          <input class=\"nhsuk-checkboxes__input\" id=\"symptoms-none\" name=\"symptoms[none]\" type=\"checkbox\" value=\"yes\" data-checkbox-exclusive=\"\" data-checkbox-exclusive-group=\"symptoms\">\n",
      "after": "          <input class=\"nhsuk-checkboxes__input\" id=\"symptoms-none\" name=\"symptoms[none]\" type=\"checkbox\" value=\"yes\" data-checkbox-exclusive=\"true\" data-checkbox-exclusive-group=\"symptoms\">\n"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can now clear all symptom selections by activating the exclusive 'No symptoms' checkbox, meeting WCAG 2.1.1 Keyboard and 2.4.3 Focus Order requirements.",
  "functional_risks": [
    "If the checkboxes component relies on the absence of a value for data-checkbox-exclusive, explicitly setting it to \"true\" could interfere with other instances; however, the NHSUK component treats any truthy value as active, so risk is low."
  ],
  "verification_requirements": [
    "Verify that selecting 'No symptoms' clears any previously selected symptom checkboxes via keyboard (Space) and mouse.",
    "Verify that selecting any symptom checkbox after 'No symptoms' unchecks 'No symptoms'.",
    "Ensure form data reflects the correct state after each interaction.",
    "Confirm that the contact group exclusive behavior remains unchanged."
  ]
}
